import{_ as n,a0 as p,w as i,s as l,ao as d,I as s,x as a,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"“安全”这个热词：应避免使用还是该更直接了当？ | LCTT x X-CMD","titleTemplate":false,"description":"“安全”这个热词：应避免使用还是该更直接了当？ | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“安全”这个热词：应避免使用还是该更直接了当？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“安全”这个热词：应避免使用还是该更直接了当？ | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20220920 Security buzzwords to avoid and what to say instead","title":"“安全”这个热词：应避免使用还是该更直接了当？","tag":"202310","desc":""},"relativePath":"202310/20220920 Security buzzwords to avoid and what to say instead.md","filePath":"[post].md"}'),u={name:"202310/20220920 Security buzzwords to avoid and what to say instead.md"};function m(h,t,g,f,b,T){const e=p("Link");return i(),l("div",null,[t[15]||(t[15]=d('<h1 id="安全-这个热词-应避免使用还是该更直接了当" tabindex="-1">“安全”这个热词：应避免使用还是该更直接了当？ <a class="header-anchor" href="#安全-这个热词-应避免使用还是该更直接了当" aria-label="Permalink to ““安全”这个热词：应避免使用还是该更直接了当？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/28/095718zso6aaitoyyv4ain.jpg" alt=""></p><blockquote><p>思考一下，如何在你的开源项目中真正定义安全性吧。</p></blockquote><p>科技行业以创造“热词”而小有名气，当然，其他行业也是如此。譬如，“故事驱动”和“轻规则”是当下流行的桌游概念，“解构”的汉堡和墨西哥卷饼在高级餐厅颇受欢迎。然而，技术热词的问题在于，它们可能直接影响你的生活。当某人标榜应用程序“安全”，以此来吸引你使用他们的产品，产品实际上是在暗示一种承诺：“安全”的含义就是它是安全的，它值得你的使用与信任。但问题是，“安全”这个词可能指的是许多事情，技术行业常将它用作一个过于泛化的术语，以至于它逐渐失去了实际含义。</p><p>由于“安全”一词可能含义丰富，也可能一无是处，使用它就需要慎之又慎。事实上，最好是尽量避免使用这个词，取而代之的是，诉诸你真正要表达的东西。</p><h3 id="当-安全-意味着加密" tabindex="-1">当 “安全” 意味着加密 <a class="header-anchor" href="#当-安全-意味着加密" aria-label="Permalink to “当 “安全” 意味着加密”">​</a></h3><p>有时候，“安全” 会被作为 <em>加密</em> 的非常不明确的简短表述。在这种情况下，“安全” 指的是，对于外部观察者想要窃听你的数据，要经过一定的困难。</p><p><strong>避免这样表述：</strong>“本网站稳如磐石且安全无忧。”</p><p>听起来很棒？你可能会想象一个拥有多重二次验证、零知识证明数据存储以及坚决的匿名策略的网站。</p><p><strong>你可以这么说：</strong>“本网站承诺有 99% 的在线时间，并且其流量都通过 SSL 进行加密和验证。”</p><p>这样一来，承诺的含义变得清晰了，同时也明确了实现 “安全” 的方法（即使用 SSL）以及 “安全“ 的作用范围是什么。</p><p>注意，这里并未对隐私或匿名做出任何明确的承诺。</p><h3 id="当-安全-意味着访问限制" tabindex="-1">当 “安全” 意味着访问限制 <a class="header-anchor" href="#当-安全-意味着访问限制" aria-label="Permalink to “当 “安全” 意味着访问限制”">​</a></h3><p>有时，“安全” 这个词是指应用程序或设备的访问权限。如果没有明确的解释，“安全” 可能涵盖从无效的“隐蔽即安全”模式，到简单的 htaccess 密码，直到生物识别扫描器等各种概念。</p><p><strong>避免这样表述：</strong>“我们已经为你防护好了系统。”</p><p><strong>你可以这么说：</strong>“我们的系统采用了二步验证法。”</p><h3 id="当-安全-意味着数据存储" tabindex="-1">当 “安全” 意味着数据存储 <a class="header-anchor" href="#当-安全-意味着数据存储" aria-label="Permalink to “当 “安全” 意味着数据存储”">​</a></h3><p>“安全” 这个词也可以指你的数据在服务器或设备上的储存方法。</p><p><strong>避免这样表述：</strong>“这个设备在数据存储上考虑了安全因素。”</p><p><strong>你可以这么说：</strong>“这个设备利用全盘加密技术来保护你的数据。”</p><p>当提到远程存储时，“安全” 可能更多指的是谁可以访问存储数据。</p><p><strong>避免这样表述：</strong>“你的数据是安全的。”</p><p><strong>你可以这么说：</strong>“你的数据经过 PGP 加密，仅你持有私钥。”</p><h3 id="当-安全-意味着隐私" tabindex="-1">当 “安全” 意味着隐私 <a class="header-anchor" href="#当-安全-意味着隐私" aria-label="Permalink to “当 “安全” 意味着隐私”">​</a></h3><p>今天，“隐私” 一词几乎和 “安全” 一样宽泛且模糊。一方面，“安全” 似乎必然就涉及 “隐私”，然而，这仅在 &#39;安全&#39; 有明确定义时才成立。是因为设有密码阻止外人进入所以称之为私有吗？还是因为数据已加密且仅你拥有密钥所以归为私有？又或者，由于存储你数据的厂商除了 IP 地址外对你一无所知，这才算是私有？光是口头声明 “隐私”，就像未经说明就声明 “安全” 一样，是不够的。</p><p><strong>避免这样表述：</strong>“你的数据在我们这里是安全的。”</p><p><strong>你可以这么说：</strong>“你的数据经 PGP 加密，且只有你拥有私钥。我们不需要你的任何个人信息，唯一能识别你的只有你的 IP 地址。”</p><p>一些网站会声明 IP 地址在日志中保留期限，及非经法律授权绝不向执法部门交出用户数据等诸多承诺。虽然这些并不属于技术 “安全” 的范畴，但它们全都涉及的是信任度，你不能将这些看作是技术规格。</p><h3 id="明确所说" tabindex="-1">明确所说 <a class="header-anchor" href="#明确所说" aria-label="Permalink to “明确所说”">​</a></h3><p>科技是个复杂的话题，极易引发混淆。沟通是至关重要的，虽然有时候简拼和专有名词在某些场合可能管用，但通常来说，讲明白总是比较好的。当你对你的项目的 “安全” 感到自豪，不要只用模糊的词语进行简述。向其他人明确你具体做了什么来保护你的用户，同时也要明确你认为哪些事物已超出你的考量范围，并要经常进行这样的沟通。“安全” 是个好特点，但它的涵盖面过广，所以请勿畏于夸赞自己在某个具体方向上的特别之处。</p><p><em>（题图：MJ/b8cc54ee-5556-4106-b9fa-b08539452aa7）</em></p><hr>',32)),s("p",null,[t[1]||(t[1]=a("via: ",-1)),r(e,{href:"https://opensource.com/article/22/9/security-buzzword-alternatives"},{default:o(()=>[...t[0]||(t[0]=[a("https://opensource.com/article/22/9/security-buzzword-alternatives",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=a("作者：",-1)),r(e,{href:"https://opensource.com/users/seth"},{default:o(()=>[...t[2]||(t[2]=[a("Seth Kenlon",-1)])]),_:1}),t[7]||(t[7]=a(" 选题：",-1)),r(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[3]||(t[3]=[a("lkxed",-1)])]),_:1}),t[8]||(t[8]=a(" 译者：",-1)),r(e,{href:"https://linux.cn/lctt/ChatGPT"},{default:o(()=>[...t[4]||(t[4]=[a("ChatGPT",-1)])]),_:1}),t[9]||(t[9]=a(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=a("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[a("Linux中国",-1)])]),_:1}),t[14]||(t[14]=a(" 荣誉推出",-1))])])}const k=n(u,[["render",m]]);export{C as __pageData,k as default};
